class CsvError(Exception):
    def __init__(self, message, line=0, col=0):
        super().__init__(message)
        self.line = line
        self.col = col


def parse(text: str, dialect: dict) -> list:
    if text.startswith("\ufeff"):
        text = text[1:]

    if dialect is None:
        dialect = {}

    delimiter = dialect.get("delimiter", ",")
    quote = dialect.get("quote", '"')
    escape = dialect.get("escape", None)
    skip_initial_space = dialect.get("skip_initial_space", False)
    comment = dialect.get("comment", None)
    skip_blank = dialect.get("skip_blank", True)
    strict = dialect.get("strict", True)
    header = dialect.get("header", False)
    fill = dialect.get("fill", None)
    null_values = dialect.get("null_values", [])
    if null_values is None:
        null_values = []
    infer_ints = dialect.get("infer_ints", False)
    trim = dialect.get("trim", False)

    n = len(text)
    idx = 0
    line = 1
    col = 1

    def is_break(i):
        return i < n and (text[i] == "\r" or text[i] == "\n")

    def break_len(i):
        if text[i] == "\r" and i + 1 < n and text[i + 1] == "\n":
            return 2
        return 1

    def consume_break():
        nonlocal idx, line, col
        length = break_len(idx)
        s = text[idx:idx + length]
        idx += length
        line += 1
        col = 1
        return s

    def consume_char():
        nonlocal idx, col
        ch = text[idx]
        idx += 1
        col += 1
        return ch

    def is_ascii_int(s):
        if not s:
            return False
        if s[0] == "-":
            digits = s[1:]
        else:
            digits = s
        if not digits:
            return False
        for ch in digits:
            if ch < "0" or ch > "9":
                return False
        return True

    def finalize_unquoted(acc, postprocess):
        s = "".join(acc)
        if not postprocess:
            return s
        if trim:
            s = s.strip(" \t")
        if s in null_values:
            return None
        if infer_ints and is_ascii_int(s):
            return int(s)
        return s

    def parse_unquoted(postprocess):
        acc = []
        while idx < n:
            if text[idx] == delimiter:
                consume_char()
                return finalize_unquoted(acc, postprocess), "delimiter"
            if is_break(idx):
                consume_break()
                return finalize_unquoted(acc, postprocess), "linebreak"
            acc.append(text[idx])
            consume_char()
        return finalize_unquoted(acc, postprocess), "eof"

    def parse_quoted():
        open_line, open_col = line, col
        consume_char()
        content = []

        while True:
            if idx >= n:
                raise CsvError("unterminated quoted field", open_line, open_col)

            if is_break(idx):
                content.append(consume_break())
                continue

            ch = text[idx]

            if escape is None:
                if ch == quote:
                    if idx + 1 < n and text[idx + 1] == quote:
                        content.append(quote)
                        consume_char()
                        consume_char()
                        continue
                    consume_char()
                    break
                content.append(ch)
                consume_char()
            else:
                if ch == escape:
                    consume_char()
                    if idx >= n:
                        raise CsvError("unterminated quoted field", open_line, open_col)
                    if is_break(idx):
                        content.append(consume_break())
                    else:
                        content.append(consume_char())
                    continue
                if ch == quote:
                    consume_char()
                    break
                content.append(ch)
                consume_char()

        field = "".join(content)

        if idx < n and text[idx] != delimiter and not is_break(idx):
            if strict:
                raise CsvError("unexpected character after closing quote", line, col)
            tail = []
            while idx < n and text[idx] != delimiter and not is_break(idx):
                tail.append(text[idx])
                consume_char()
            field += "".join(tail)

        if idx < n and text[idx] == delimiter:
            consume_char()
            return field, "delimiter"

        if idx < n and is_break(idx):
            consume_break()
            return field, "linebreak"

        return field, "eof"

    def parse_field(postprocess):
        if skip_initial_space:
            while idx < n and text[idx] == " ":
                consume_char()

        if quote is not None and idx < n and text[idx] == quote:
            return parse_quoted()

        return parse_unquoted(postprocess)

    result = []
    header_names = None

    def add_record(record):
        nonlocal header_names

        if not header:
            result.append(record)
            return

        if header_names is None:
            names = []
            counts = {}
            for pos, raw in enumerate(record, 1):
                name = raw if isinstance(raw, str) else str(raw)
                if name == "":
                    name = f"col{pos}"

                seen = counts.get(name, 0)
                if seen >= 1:
                    final_name = f"{name}_{seen + 1}"
                else:
                    final_name = name

                counts[name] = seen + 1
                names.append(final_name)

            header_names = names
        else:
            row = {}
            hlen = len(header_names)

            for i, name in enumerate(header_names):
                if i < len(record):
                    row[name] = record[i]
                else:
                    row[name] = fill

            if len(record) > hlen:
                row["_extra"] = record[hlen:]

            result.append(row)

    while True:
        if idx >= n:
            break

        if is_break(idx):
            if skip_blank:
                consume_break()
            else:
                consume_break()
                postprocess = not (header and header_names is None)
                add_record([finalize_unquoted([], postprocess)])
            continue

        if comment is not None and text[idx] == comment:
            while idx < n and not is_break(idx):
                consume_char()
            if idx < n and is_break(idx):
                consume_break()
            continue

        postprocess = not (header and header_names is None)
        record = []

        while True:
            value, terminator = parse_field(postprocess)
            record.append(value)
            if terminator != "delimiter":
                break

        add_record(record)

        if terminator == "eof":
            break

    return result
